CustomField.formula:
IF(RecordType.DeveloperName = 'Budgeted_Initiative',
   IF(ISBLANK(Term__c),
   	null,
        IF( Approved__c , 
	       IF(ISBLANK(Approved_Amount__c),
               null,
               ROUND((Approved_Amount__c / Term__c) * 12,0)
           ),
           IF(ISBLANK(Proposed_Amount__c),
               null,
               ROUND((Proposed_Amount__c / Term__c) * 12,0)
           )
        )
   ),
   null
)
